export const meta = {
  name: 'audit-family-data',
  description: 'Audit the in-family training data against DecisionBench family definitions and find mismatches',
  phases: [{ title: 'Audit', detail: 'one auditor per family group' }, { title: 'Verify', detail: 'refute each mismatch' }],
}
const GROUPS = [
  ['routing','classification','intent_detection','tool_selection','function_selection'],
  ['verification','citation_check','claim_verification','fact_check','consistency_check'],
  ['extraction_selection','value_selection','entity_resolution','span_selection'],
  ['moderation','online_safety','policy_compliance','legal','risk_assessment'],
  ['ranking','reranking','relevance','priority','scoring'],
  ['financial','medical','support','reasoning','other'],
]
const FINDINGS = { type: 'object', properties: { mismatches: { type: 'array', items: { type: 'object', properties: {
  family: { type: 'string' }, problem: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' } },
  required: ['family','problem','evidence','fix'] } } }, required: ['mismatches'] }
const VERDICT = { type: 'object', properties: { refuted: { type: 'boolean' }, reason: { type: 'string' } }, required: ['refuted','reason'] }
const results = await pipeline(GROUPS,
  (g, _, i) => agent(`You are auditing training data for a System One decision model in /home/user/projects/biff.
Families to audit (names may not all exist; skip missing ones): ${g.join(', ')}.
Steps: (1) Read s1/families.py for how each family's rows are generated. (2) Read research/decisionbench_card.md and, using python with pandas, read the DecisionBench parquet at ~/.cache/huggingface/hub/datasets--Hanno-Labs--decision-bench/snapshots/*/data/eval-00000-of-00001.parquet, filter to these families, and inspect 10 rows per family: state shape, question wording, option count, criteria style, primitive. Benchmark rows are NEVER to be copied into training; you are only comparing shape and intent. (3) Read 10 generated rows per family from data/train.jsonl (filter by the source/family field). (4) Report every concrete mismatch between generated and benchmark rows: primitive, option count distribution, state length, state structure, question phrasing, presence of a none option, label noise, domain coverage. Quote evidence. Propose a specific code fix for each. Do not modify any file.`,
    { label: `audit:${i}`, phase: 'Audit', schema: FINDINGS }),
  (r) => r ? parallel(r.mismatches.map(m => () =>
    agent(`Try to refute this claimed mismatch in biff's in-family training data. Family: ${m.family}. Claim: ${m.problem}. Evidence given: ${m.evidence}. Check s1/families.py, data/train.jsonl and the DecisionBench parquet yourself (read only). Default to refuted=true if the evidence does not hold up or the mismatch would not plausibly cost accuracy on the benchmark.`,
      { label: `verify:${m.family}`, phase: 'Verify', schema: VERDICT }).then(v => ({ ...m, verdict: v })))) : []
)
const confirmed = results.flat().filter(Boolean).filter(m => m.verdict && !m.verdict.refuted)
log(`${confirmed.length} confirmed mismatches of ${results.flat().filter(Boolean).length} claimed`)
return { confirmed }

